import { useQueryClient } from '@tanstack/react-query';
import { gradeOn, liveHolds } from '../people/people';
import { personDue } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { dueRules } from '../settings/settings';
import { freshClaims, freshPeople, freshPools, freshRates, freshSettings, freshSheetInfo } from './fresh';

/** A CSV field: wrapped in double quotes, with any quote inside doubled, when it holds a comma, a quote or a line break. */
export function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

// The button that downloads the people as a CSV file: one line per person in list order, retired
// people included, with the grade in force on the sheet's today, the retired-from date (or nothing)
// and the due-total as shown. Lines end with a line feed. The sheet is re-read from the store first, so
// while the screen is shown as of a date the lines are as of that date.
export function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();

  if (!user || !sheet) return null;

  const download = async () => {
    const [info, people, claims, rates, settings, pools] = await Promise.all([
      freshSheetInfo(queryClient, sheet),
      freshPeople(queryClient, sheet),
      freshClaims(queryClient, sheet),
      freshRates(queryClient, sheet),
      freshSettings(queryClient, sheet),
      freshPools(queryClient, sheet),
    ]);
    const today = info.today;
    const rules = dueRules(settings, today, claims, pools);
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const due = personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules, {
        personId: p.id,
        claims,
        people,
      });
      lines.push([p.name, gradeOn(p.grades, today) ?? p.grade, p.retiredFrom ?? '', due]);
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export people (CSV)
    </button>
  );
}
import type { QueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { claimsKey } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { periodsKey } from '../periods/periods';
import type { Period } from '../periods/periods';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { poolsKey } from '../pools/pools';
import type { Pool } from '../pools/pools';
import { ratesKey } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { sheetInfoKey } from '../session/session';
import type { SheetInfo } from '../session/session';
import { settingsKey } from '../settings/settings';
import type { Settings } from '../settings/settings';

/**
 * One part of the sheet re-read from the store under its usual query key, so an export never builds
 * from what the screen last held: while the screen is shown as of a date (the read carries it), the
 * export takes the as-of figures even when the screen has not yet re-read them.
 */
function fresh<T>(queryClient: QueryClient, queryKey: readonly unknown[], path: string): Promise<T> {
  return queryClient.fetchQuery({ queryKey, queryFn: () => getJson<T>(path), staleTime: 0 });
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;

export const freshSheetInfo = (qc: QueryClient, sheet: string) => fresh<SheetInfo>(qc, sheetInfoKey(sheet), base(sheet));
export const freshPeople = (qc: QueryClient, sheet: string) => fresh<Person[]>(qc, peopleKey(sheet), `${base(sheet)}/people`);
export const freshClaims = (qc: QueryClient, sheet: string) => fresh<Claim[]>(qc, claimsKey(sheet), `${base(sheet)}/claims`);
export const freshRates = (qc: QueryClient, sheet: string) => fresh<Rate[]>(qc, ratesKey(sheet), `${base(sheet)}/rates`);
export const freshPeriods = (qc: QueryClient, sheet: string) => fresh<Period[]>(qc, periodsKey(sheet), `${base(sheet)}/periods`);
export const freshSettings = (qc: QueryClient, sheet: string) => fresh<Settings>(qc, settingsKey(sheet), `${base(sheet)}/settings`);
export const freshPools = (qc: QueryClient, sheet: string) => fresh<Pool[]>(qc, poolsKey(sheet), `${base(sheet)}/pools`);
import { Fragment } from 'react';
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import { personPeriodCarried, personPeriodDue, usePeriods } from './periods';

// A person's due-total for each period on the sheet, one cell per period; fixed while the period is closed. Beside
// each, the figure carried into it from earlier periods.
export function PersonPeriodDue({ person }: { person: Person }) {
  const periods = usePeriods().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <td data-testid={`person-period-${p.name}-due-total`}>{personPeriodDue(p, person, claims, rates, rules)}</td>
          <td data-testid={`person-period-${p.name}-carried`}>{personPeriodCarried(p, periods, person, claims, rates, rules)}</td>
        </Fragment>
      ))}
    </>
  );
}

// A head for each period's column.
export function PersonPeriodHeads() {
  const periods = usePeriods().data ?? [];
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <th>{p.name} due</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}
